import{_ as a,o as e,c as s,a4 as n}from"./chunks/framework.BBs01uty.js";const g=JSON.parse('{"title":"Node.js 高并发与高可用设计","description":"","frontmatter":{},"headers":[],"relativePath":"service/node-high-concurrency.md","filePath":"service/node-high-concurrency.md"}'),o={name:"service/node-high-concurrency.md"};function d(r,t,i,l,p,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="node-js-高并发与高可用设计" tabindex="-1">Node.js 高并发与高可用设计 <a class="header-anchor" href="#node-js-高并发与高可用设计" aria-label="Permalink to &quot;Node.js 高并发与高可用设计&quot;">​</a></h1><blockquote><p><strong>优先级：P1</strong> — 理解 Node 能扛并发的前提（单线程事件循环），再谈&quot;怎么设计让它高并发高可用&quot;。本文不背代码，讲<strong>设计决策</strong>。</p></blockquote><h2 id="一、先理解-node-的并发模型-为什么它能扛-io-密集" tabindex="-1">一、先理解 Node 的并发模型（为什么它能扛 IO 密集） <a class="header-anchor" href="#一、先理解-node-的并发模型-为什么它能扛-io-密集" aria-label="Permalink to &quot;一、先理解 Node 的并发模型（为什么它能扛 IO 密集）&quot;">​</a></h2><p>Node 是<strong>单线程事件循环 + 异步 IO</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主线程（一个）</span></span>
<span class="line"><span>  ├─ 请求进来 → 注册回调（不等待）→ 处理下一个</span></span>
<span class="line"><span>  ├─ IO 完成（DB/网络/文件）→ 事件循环唤醒回调 → 续上</span></span>
<span class="line"><span>  └─ 单个慢请求不阻塞其他请求（await 只挂起&quot;当前逻辑流&quot;）</span></span></code></pre></div><p><strong>优势</strong>：IO 密集场景下，一个进程能同时挂几万个等待中的请求，内存占用远小于&quot;每请求一线程&quot;的 Java。</p><p><strong>短板</strong>：纯 CPU 计算（JSON 大解析、加密、图像处理）会<strong>阻塞事件循环</strong>——期间所有请求卡住。</p><blockquote><p><strong>高并发的第一原则</strong>：把 CPU 密集工作挪出主线程（worker_threads / 拆到别的服务 / MQ）。</p></blockquote><h2 id="二、高并发设计-单机怎么扛更多" tabindex="-1">二、高并发设计（单机怎么扛更多） <a class="header-anchor" href="#二、高并发设计-单机怎么扛更多" aria-label="Permalink to &quot;二、高并发设计（单机怎么扛更多）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>手段</th><th>做什么</th><th>解决什么</th></tr></thead><tbody><tr><td><strong>全程异步 IO</strong></td><td>用 fs/promises、<code>await</code> 数据库，<strong>绝不调阻塞版 API</strong>（如 <code>readFileSync</code>）</td><td>别自己堵死事件循环</td></tr><tr><td><strong>cluster 多进程</strong></td><td>起 N 个 worker 进程吃满多核（Node 单进程只用一个核）</td><td>单核 → 多核</td></tr><tr><td><strong>worker_threads</strong></td><td>CPU 密集任务丢线程池</td><td>主线程不被计算卡住</td></tr><tr><td><strong>PM2 fork 模式</strong></td><td><code>pm2 start app.js -i max</code>（多实例 + 自动重启）</td><td>多核 + 进程守护</td></tr><tr><td><strong>nginx 反代前置</strong></td><td>静态资源 nginx 直接吐、动态走 Node</td><td>减少 Node 负担 + keepalive</td></tr></tbody></table><p><strong>为什么 nginx 前置</strong>：Node 不擅长静态文件/连接管理，nginx（C 写的、事件模型更极致）在前面挡静态 + 负载均衡，Node 专注业务。</p><h2 id="三、高可用设计-挂了-多了也不出事" tabindex="-1">三、高可用设计（挂了/多了也不出事） <a class="header-anchor" href="#三、高可用设计-挂了-多了也不出事" aria-label="Permalink to &quot;三、高可用设计（挂了/多了也不出事）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>无状态化：session/token 外置（Redis）→ 任何实例都能接任何请求</span></span>
<span class="line"><span>         （这是&quot;能水平扩展&quot;的前提）</span></span>
<span class="line"><span>负载均衡：nginx / 云 LB 分发到多实例 + 健康检查（自动摘掉挂的）</span></span>
<span class="line"><span>进程守护：PM2/cluster 崩溃自动重启（单点进程挂了能自愈）</span></span>
<span class="line"><span>超时/熔断：外部调用设超时 + 熔断降级（依赖挂了给兜底，别连锁崩）</span></span>
<span class="line"><span>日志监控：请求日志（ELK/Sentry）+ 健康检查端点</span></span></code></pre></div><p><strong>核心认知</strong>：单实例再优化也有上限，<strong>高可用 = 多实例 + 无状态 + 自动摘除 + 自愈</strong>。</p><h2 id="四、什么时候不该硬扛-识别瓶颈" tabindex="-1">四、什么时候不该硬扛（识别瓶颈） <a class="header-anchor" href="#四、什么时候不该硬扛-识别瓶颈" aria-label="Permalink to &quot;四、什么时候不该硬扛（识别瓶颈）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CPU 密集重负载（视频转码/大规模计算） → Node 不合适，交给 Go/Rust/专用服务</span></span>
<span class="line"><span>复杂事务/强一致性业务 → 数据库才是瓶颈，语言救不了</span></span>
<span class="line"><span>如果 QPS 高但都是 IO（查缓存/查库）→ Node 合适，先看 DB/Redis 扛不扛得住</span></span></code></pre></div><h2 id="五、实践清单" tabindex="-1">五、实践清单 <a class="header-anchor" href="#五、实践清单" aria-label="Permalink to &quot;五、实践清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>清单项</th><th>说明</th></tr></thead><tbody><tr><td>别用阻塞 API</td><td>同步读文件等 = 自杀式写法</td></tr><tr><td>请求进 Node 前先挡一层</td><td>nginx 静态 + 限流 + 负载均衡</td></tr><tr><td>多核用 cluster/PM2 -i</td><td>单进程只吃一个核是浪费</td></tr><tr><td>CPU 任务丢 worker</td><td>别让计算堵死主线程</td></tr><tr><td>无状态化</td><td>session 外置，实例才能随便扩</td></tr><tr><td>进程守护</td><td>崩溃自愈（PM2/集群）</td></tr><tr><td>外部依赖熔断</td><td>超时 + 降级，防连锁雪崩</td></tr><tr><td>监控前置</td><td>日志/指标先上线，出事能定位</td></tr></tbody></table><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><blockquote><p>Node 高并发的底气是<strong>单线程事件循环</strong>（IO 密集省资源），设计关键：<strong>异步到底 + 多进程吃满核 + CPU 任务挪走 + 无状态多实例 + 进程守护</strong>；高可用靠&quot;多实例 + 负载均衡 + 自愈&quot;，不是单进程硬扛。<strong>识别短板</strong>（CPU 密集）比堆优化更重要——瓶颈在 DB 或计算时，先解决那里。</p></blockquote><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/knowledge/service/node-vs-java.html">Node.js vs Java 后端选型</a> - 并发模型的选型对比</li><li><a href="/knowledge/service/java-high-concurrency.html">Java 高并发与高可用设计</a> - 另一侧的并发模型</li><li><a href="/knowledge/service/docker.html">Docker 入门</a> - 多实例部署的基础</li></ul>`,22)])])}const u=a(o,[["render",d]]);export{g as __pageData,u as default};
